				t.Fatalf("route series = %+v", chart.Series)
			}
			points := chart.Series[0].Points
			if rangeID == "15m" {
				if len(points) != 3 || points[0][1] != .00001337 || points[1][1] != .009 || points[2][1] != .00001337 {
