func newTestDashboard(options Options) *Dashboard {
	options.Now = func() time.Time { return testNow }
	if options.Interval == 0 {
		options.Interval = 20 * time.Millisecond
	}
	return New(options)
}

func get(t *testing.T, handler http.Handler, path string) *httptest.ResponseRecorder {
	t.Helper()
	recorder := httptest.NewRecorder()
	request := httptest.NewRequest(http.MethodGet, path, nil)
	handler.ServeHTTP(recorder, request)
	return recorder
}

func newStreamServer(t *testing.T, dashboard *Dashboard) *httptest.Server {
	t.Helper()
	server := httptest.NewServer(dashboard.Handler())
	t.Cleanup(server.Close)
	return server
}

// sseReader reads Datastar events from a live stream.
type sseReader struct {
	t       *testing.T
	scanner *bufio.Scanner
}

func openStream(t *testing.T, server *httptest.Server, path string) (*sseReader, *http.Response) {
	t.Helper()
	ctx, cancel := context.WithCancel(t.Context())
	t.Cleanup(cancel)
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, server.URL+path, nil)
	if err != nil {
		t.Fatal(err)
	}
	request.Header.Set("Datastar-Request", "true")
	response, err := server.Client().Do(request)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = response.Body.Close() })
	return &sseReader{t: t, scanner: bufio.NewScanner(response.Body)}, response
}

// next returns the type and joined data lines of the next event.
func (reader *sseReader) next() (string, string) {
	reader.t.Helper()
	var eventType string
	var data []string
	for reader.scanner.Scan() {
		line := reader.scanner.Text()
		switch {
		case line == "" && eventType != "":
			return eventType, strings.Join(data, "\n")
		case strings.HasPrefix(line, "event: "):
			eventType = strings.TrimPrefix(line, "event: ")
		case strings.HasPrefix(line, "data: "):
			data = append(data, strings.TrimPrefix(line, "data: "))
		}
	}
	reader.t.Fatalf("stream ended: %v", reader.scanner.Err())
	return "", ""
}

func fixturePage(t *testing.T, current view, path string) string {
	t.Helper()
	now := current.Now
	if now.IsZero() {
		now = testNow
	}
	journal := Journal{}
	if current.Journal != nil {
		journal = *current.Journal
	}
	if current.LocalSummary != nil {
		journal.Local = func(context.Context) regionview.Summary { return *current.LocalSummary }
	}
	if current.Global != nil {
		cells := make([]string, 0, len(current.Global))
		for _, region := range current.Global {
			cells = append(cells, region.Cell)
		}
		local := ""
		if len(cells) > 0 {
			local = cells[0]
		}
		journal.Global = globalview.NewView(local, func() []string { return cells }, func() time.Time { return now })
		for _, region := range current.Global {
			if region.Rollup == nil {
				continue
			}
			rollup := *region.Rollup
			rollup.Version, rollup.Cell = globalview.Version, region.Cell
			if rollup.ObservedAt.IsZero() {
				rollup.ObservedAt = now
			}
			if region.Stale {
				rollup.ObservedAt = now.Add(-time.Minute)
			}
			if !journal.Global.Accept(rollup) {
				t.Fatalf("invalid fixture rollup: %+v", rollup)
			}
		}
	}
	if current.Decisions != nil {
		journal.Decisions = fixtureDecisions{result: *current.Decisions}
	}
	if current.Versions != nil {
		journal.Versions = fakeVersions(current.Versions)
	}
	if current.Capacity != nil {
		journal.Capacity = &fakeCapacity{view: *current.Capacity}
	}
	if current.Evaluation != nil {
		journal.Insights = &fakeInsights{evaluation: *current.Evaluation}
	}
	options := Options{Journal: &journal, Now: func() time.Time { return now }, Health: fixtureHealth{current.Ready, current.Checks}}
	if current.Local != nil {
		options.Snapshots = fixedSnapshots{snapshot: *current.Local}
	}
	if current.Cluster != nil {
		options.Cluster = fixedCluster{snapshot: *current.Cluster}
	}
	server := httptest.NewServer(New(options).Handler())
	defer server.Close()
	state := current.State
	if state.Range.Key == "" {
		state = parseState(nil)
	}
	if query := state.query(); query != "" {
		path += "?" + query
	}
	client := server.Client()
	client.Timeout = 5 * time.Second
	response, err := client.Get(server.URL + path)
	if err != nil {
		t.Fatal(err)
	}
	defer response.Body.Close()
	body, err := io.ReadAll(response.Body)
	if err != nil {
		t.Fatal(err)
	}
	if response.StatusCode != http.StatusOK {
		t.Fatalf("GET %s = %d: %s", path, response.StatusCode, body)
	}
	return string(body)
}

type fixtureDecisions struct{ result decisionlog.Result }

func (source fixtureDecisions) Query(context.Context, decisionlog.Query) (decisionlog.Result, error) {
	return source.result, nil
}
func (source fixtureDecisions) Chain(context.Context, string) (decisionlog.Chain, error) {
	return decisionlog.Chain{}, decisionlog.ErrNotFound
}

type fixtureHealth struct {
	ready  bool
	checks []observability.CheckResult
}

func (source fixtureHealth) Evaluate(context.Context) (bool, []observability.CheckResult) {
	return source.ready, source.checks
}

func pageCharts(t *testing.T, body string) []chartSpec {
	t.Helper()
	var charts []chartSpec
	for _, match := range regexp.MustCompile(`data-spec="([^"]*)"`).FindAllStringSubmatch(body, -1) {
		var spec chartSpec
		if err := json.Unmarshal([]byte(html.UnescapeString(match[1])), &spec); err != nil {
			t.Fatal(err)
		}
		charts = append(charts, spec)
	}
	return charts
}

func New(options Options) *Dashboard {
	if options.Interval <= 0 {
		options.Interval = DefaultInterval
	}
	if options.MaxStreams <= 0 {
		options.MaxStreams = DefaultMaxStreams
	}
	if options.Now == nil {
		options.Now = time.Now
	}
	dashboard := &Dashboard{options: options, streams: make(chan struct{}, options.MaxStreams),
		decisions: newKeyedCache[decisionlog.Result](decisionCacheTTL, 64),
		rollouts:  newKeyedCache[[]insights.Rollout](decisionCacheTTL, 1),
		rollout:   newKeyedCache[insights.Rollout](decisionCacheTTL, 64),
		chains:    newKeyedCache[decisionlog.Chain](decisionCacheTTL, 64),
		summaries: newKeyedCache[insights.Summary](summaryCacheTTL, 8)}
	dashboard.clusters.TTL = clusterCacheTTL
	dashboard.SetSnapshots(options.Snapshots)
	dashboard.SetCluster(options.Cluster)
	if options.Journal != nil {
		dashboard.SetJournal(*options.Journal)
	}
	return dashboard
}

// SetJournal attaches the decision journal, history, insight, summary and
// region providers.
func (dashboard *Dashboard) SetJournal(journal Journal) {
	dashboard.journal.Store(&journal)
}

// SetSnapshots attaches this member's snapshot provider.
func (dashboard *Dashboard) SetSnapshots(source observability.SnapshotSource) {
	if source != nil {
		dashboard.snapshots.Store(&snapshotHolder{source: source})
	}
}

// SetCluster attaches the cell-wide provider.
func (dashboard *Dashboard) SetCluster(source observability.ClusterSource) {
	if source != nil {
		dashboard.cluster.Store(&clusterHolder{source: source})
	}
}

// Mount registers every page, its stream, the login form and the assets.
func (dashboard *Dashboard) Mount(mounter Mounter) {
	mounter.HandleStatic("GET /assets/{hash}/{file}", http.HandlerFunc(serveAsset))
	mounter.HandleLogin(dashboard.guard(http.HandlerFunc(dashboard.login)))
	for _, page := range slices.Concat(pages, detailPages) {
		mounter.Handle("GET "+page.path(), dashboard.guard(dashboard.pageHandler(page)))
		mounter.Handle("GET "+page.streamPath(), dashboard.guard(dashboard.streamHandler(page)))
	}
	mounter.Handle("POST /capacity/budget", dashboard.guard(http.HandlerFunc(dashboard.setBudget)))
}

// Handler returns the dashboard routes on their own mux without any
// authentication. Tests use it; production mounts on the private listener.
func (dashboard *Dashboard) Handler() http.Handler {
	mux := http.NewServeMux()
	dashboard.Mount(muxMounter{mux})
	return mux
}

type muxMounter struct{ mux *http.ServeMux }

func (mounter muxMounter) Handle(pattern string, handler http.Handler) {
	mounter.mux.Handle(pattern, handler)
}
func (mounter muxMounter) HandleStatic(pattern string, handler http.Handler) {
	mounter.mux.Handle(pattern, handler)
}
func (mounter muxMounter) HandleLogin(page http.Handler) { mounter.mux.Handle("GET /login", page) }

func (dashboard *Dashboard) guard(next http.Handler) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		if dashboard.options.RequireLiteralHost && !literalHost(request.Host) {
			http.Error(writer, "the dashboard must be addressed by IP or localhost", http.StatusMisdirectedRequest)
			return
		}
		header := writer.Header()
		header.Set("Content-Security-Policy", contentSecurityPolicy)
		header.Set("X-Content-Type-Options", "nosniff")
		header.Set("X-Frame-Options", "DENY")
		header.Set("Referrer-Policy", "same-origin")
		header.Set("Cache-Control", "no-store")
		next.ServeHTTP(writer, request)
	})
}

func literalHost(host string) bool { return observability.LiteralHost(host) }

// load gathers the view every page renders from. Missing providers and
// failing sections become notes on the view, never a failed request.
func (dashboard *Dashboard) load(ctx context.Context, page page, query url.Values, path map[string]string) view {
	current := view{Page: page, Now: dashboard.options.Now().UTC(), SignOut: dashboard.options.SignOut,
		Filter: parseEventFilter(query), State: parseState(query), Path: path}
	if region := path["r"]; region != "" {
		// A detail page whose path names its region shows that region.
		current.State.Region = region
	}
	if health := dashboard.options.Health; health != nil {
		current.Ready, current.Checks = health.Evaluate(ctx)
	}
	if holder := dashboard.snapshots.Load(); holder != nil {
		snapshot, err := holder.source.Snapshot(ctx, false)
		if err != nil {
			current.Notes = append(current.Notes, "This member's snapshot is unavailable.")
		} else {
			current.Local = &snapshot
		}
	} else {
		current.Notes = append(current.Notes, "This member is still starting; its providers are not attached yet.")
	}
	if holder := dashboard.cluster.Load(); holder != nil {
		snapshot, err := dashboard.clusters.Get(ctx, func(ctx context.Context) (observability.ClusterSnapshot, error) {
			return holder.source.Cluster(ctx, false)
		})
		if err != nil {
			current.Notes = append(current.Notes, "The cell-wide view is unavailable; showing this member only.")
		} else {
			current.Cluster = &snapshot
		}
	}
	if page.events > 0 && dashboard.options.Events != nil {
		current.Events = current.Filter.apply(dashboard.options.Events.Recent(0), page.events)
	}
	dashboard.loadJournal(ctx, &current)
	return current
}

func (dashboard *Dashboard) pageHandler(page page) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		path, found := page.pathValues(request)
		if !found {
			http.NotFound(writer, request)
			return
		}
		current := dashboard.load(request.Context(), page, request.URL.Query(), path)
		current.loadMetrics(request.Context())
		if page.slug == "region" && current.remote() {
			// The region page shows this member's region only; another one
			// has its own global view.
			http.Redirect(writer, request, "/regions/"+current.State.Region, http.StatusSeeOther)
			return
		}
		render(writer, request, layout(current))
	})
}

func (dashboard *Dashboard) login(writer http.ResponseWriter, request *http.Request) {
	query := request.URL.Query()
	render(writer, request, login(query.Get("failed") == "1", observability.LocalRedirectPath(query.Get("next"))))
}

func render(writer http.ResponseWriter, request *http.Request, component templ.Component) {
	var body bytes.Buffer
	if err := component.Render(request.Context(), &body); err != nil {
		level := slog.LevelWarn
		if errors.Is(err, context.Canceled) {
			// The client went away; nothing is wrong with the dashboard.
			level = slog.LevelDebug
		}
		slog.Log(request.Context(), level, "dashboard render failed", observability.ComponentKey, "dashboard", "error", err)
		http.Error(writer, "render failed", http.StatusInternalServerError)
		return
	}
	writer.Header().Set("Content-Type", "text/html; charset=utf-8")
	writer.Header().Add("Vary", "Accept-Encoding")
	if !acceptsGzip(request.Header.Get("Accept-Encoding")) {
		_, _ = writer.Write(body.Bytes())
		return
	}
	writer.Header().Set("Content-Encoding", "gzip")
	zipped := gzip.NewWriter(writer)
	_, _ = zipped.Write(body.Bytes())
	_ = zipped.Close()

func (dashboard *Dashboard) streamHandler(page page) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		if !dashboard.acquireStream() {
			writer.Header().Set("Retry-After", "10")
			http.Error(writer, "too many live dashboard streams", http.StatusServiceUnavailable)
			return
		}
		defer dashboard.releaseStream()
		path, found := page.pathValues(request)
		if !found {
			http.NotFound(writer, request)
			return
		}
		query := request.URL.Query()
		sse := datastar.NewSSE(writer, request)
		if page.slug == "region" {
			// A tab left on another region's old region page moves to its
			// global view, as the page itself does.
			if current := dashboard.load(request.Context(), page, query, path); current.remote() {
				_ = sse.Redirect("/regions/" + current.State.Region)
				return
			}
		}
		if page.slug == "events" && dashboard.options.Events != nil {
			dashboard.streamEvents(request.Context(), sse, page, query)
			return
		}
		dashboard.streamContent(request.Context(), sse, page, query, path)
	})
}

// streamContent re-renders the page content and the live parts of the page
// chrome (region switcher, attention badge) every tick, and raises a toast
// as soon as the insight engine opens or escalates an insight.
func (dashboard *Dashboard) streamContent(ctx context.Context, sse *datastar.ServerSentEventGenerator, page page,
	query url.Values, path map[string]string,
) {
	ticker := time.NewTicker(dashboard.options.Interval)
	defer ticker.Stop()
	var last uint64
	var changes <-chan insights.Change
	for {
		if changes == nil {
			if journal := dashboard.journal.Load(); journal != nil && journal.Insights != nil {
				changes = journal.Insights.Subscribe(ctx, 16)
			}
		}
		current := dashboard.load(ctx, page, query, path)
		current.loadMetrics(ctx)
		var body bytes.Buffer
		if err := page.body(current).Render(ctx, &body); err != nil {
			return
		}
		if err := chrome(current).Render(ctx, &body); err != nil {
			return
		}
		digest := fnv.New64a()
		_, _ = digest.Write(body.Bytes())
		if sum := digest.Sum64(); sum != last {
			last = sum
			if err := sse.PatchElements(body.String()); err != nil {
				return
			}
		}
		for waiting := true; waiting; {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				waiting = false
			case change, open := <-changes:
				if !open {
					changes, waiting = nil, false
					continue
				}
				if err := toast(ctx, sse, current.State, change); err != nil {
					return
				}
			}
		}
	}
}

// toast raises a toast for an opened or escalated insight.
func toast(ctx context.Context, sse *datastar.ServerSentEventGenerator, state uiState, change insights.Change) error {
	if change.Type == insights.ChangeResolved {
		return nil
	}
	var toastHTML bytes.Buffer
	if err := insightToast(state, change).Render(ctx, &toastHTML); err != nil {
		return err
	}
	return sse.PatchElements(toastHTML.String(), datastar.WithSelectorID("toasts"), datastar.WithModeAppend())
}

