func drillView(now time.Time) *globalview.View {
	global := globalview.NewView("gru", func() []string { return []string{"sfo", "fra"} }, func() time.Time { return now })
	for _, cell := range []string{"gru", "sfo"} {
		observed := now
		if cell == "sfo" {
			observed = now.Add(-time.Minute)
		}
		peers := slices.DeleteFunc([]string{"gru", "sfo", "fra"}, func(peer string) bool { return peer == cell })
		rollup := overviewRollup(cell, observed, peers)
		rollup.Nodes = rollup.Nodes[:4]
		rollup.Totals.Nodes, rollup.Totals.Ready = 4, 4
		if cell == "gru" {
			rollup.Scale = &nodescale.Status{Nodes: 4, QuorumNodes: 3, PoolNodes: 1, Want: 5, Allowance: 6,
				Action: nodescale.Up, Pressure: 0.9, Signal: nodescale.SignalCPU, Reason: "cpu 0.90 at or above 0.80 for 5m0s",
				InFlight:   &nodescale.InFlight{ID: "launch-1", Kind: nodescale.Up, Step: "launch", Started: now},
				LastChange: now.Add(-2 * time.Minute), NodeMonthlyCents: 4500, ProjectedCents: 90000, Currency: "USD"}
		}
		global.Accept(rollup)
	}
	return global
}

func drillDashboard(t *testing.T, global *globalview.View) http.Handler {
	t.Helper()
	return newTestDashboard(Options{Snapshots: fixedSnapshots{snapshot: memberSnapshot()},
		Journal: &Journal{Global: global}}).Handler()
}

func overviewRollup(cell string, observed time.Time, peers []string) globalview.Rollup {
	rollup := globalview.Rollup{Version: globalview.Version, Cell: cell, ObservedAt: observed,
		Health:      globalview.Health{Status: globalview.Healthy},
		Controllers: globalview.Controllers{Expected: 3, Ready: 3, Leader: cell + "-ctl-1"},
		Totals: globalview.Totals{Nodes: 12, Ready: 12, CPUCores: 96, CPUUsedCores: 24,
			MemoryBytes: 384 << 30, MemoryUsedBytes: 192 << 30, DiskBytes: 6000 << 30, DiskUsedBytes: 1200 << 30,
			NetworkRxBps: 12000, NetworkTxBps: 6000, Load1: 6},
		Replication: globalview.Replication{LagSeconds: floatPtr(1.5)},
		Cost:        &globalview.Cost{Currency: "USD", PerHour: 12.5, MonthForecast: 9000, ObservedAt: observed},
		Autoscale: globalview.Autoscale{Services: []globalview.Scaling{
			{Service: "api", Replicas: 3, Goal: 3}, {Service: "worker", Replicas: 2, Goal: 4},
			{Service: "db", Replicas: 1, Goal: 1}, {Service: "cache", Replicas: 2, Goal: 2}}},
	}
	for index := range 12 {
		rollup.Nodes = append(rollup.Nodes, globalview.Node{Name: fmt.Sprintf("%s-n%02d", cell, index),
			Health: globalview.NodeOK, ReportedAt: observed, CPU: floatPtr(0.25), CPUCores: 8,
			MemoryBytes: 32 << 30, MemoryUsedBytes: 16 << 30, DiskBytes: 500 << 30, DiskUsedBytes: 100 << 30,
			NetworkRxBps: floatPtr(1000), NetworkTxBps: floatPtr(500), Load1: floatPtr(0.5),
			Services: []globalview.Service{{Role: "controller", State: "ready", Digest: "sha256:abc"},
				{Role: "terrabase", State: "serving"}, {Role: "nats", State: "ready"}},
			Filesystems: []globalview.Filesystem{{Role: "root", SizeBytes: 100 << 30, UsedBytes: 40 << 30},
				{Role: "state", SizeBytes: 400 << 30, UsedBytes: 60 << 30}}})
	}
	for index := range 4 {
		rollup.Volumes = append(rollup.Volumes, globalview.Volume{ID: fmt.Sprintf("%s-vol-%d", cell, index),
			Node: fmt.Sprintf("%s-n%02d", cell, index), State: "attached"})
	}
	for _, peer := range peers {
		rollup.Links = append(rollup.Links, globalview.Link{Region: peer, Reach: decisionlog.RegionOK,
			RTTMillis: floatPtr(40), LagSeconds: floatPtr(2), ObservedAt: observed})
	}
	for index := range 6 {
		rollup.Routes = append(rollup.Routes, globalview.Route{From: fmt.Sprintf("%s-ctl-%d", cell, index),
			To: cell + "-ctl-1", RTTMillis: floatPtr(0.4)})
	}
	for index := range 10 {
		rollup.Errors = append(rollup.Errors, globalview.Error{At: observed.Add(-time.Duration(index) * time.Minute),
			Level: "ERROR", Component: "orchestrator", Message: "lease renewal slow", Count: index + 1,
			Nodes: []string{cell + "-n01", cell + "-n02", cell + "-n03"}})
	}
	for index := range 10 {
		rollup.Databases = append(rollup.Databases, globalview.Database{ID: fmt.Sprintf("%s-db-%d", cell, index),
			Project: cell + "-project", ReplicationBytesPerSecond: float64(1000 * (index + 1)), LagSeconds: 1})
	}
	return rollup
}

var budgetCells = strings.Fields("gru sfo fra lhr nrt iad phx ams cdg mad mil zrh arn sin bom syd mel icn yyz jnb")

// twentyRegionView is the TS-805 budget fixture: local gru and nineteen peers,
// each with a full rollup. mel is stale.
func twentyRegionView(now time.Time) *globalview.View {
	cells := budgetCells
	global := globalview.NewView("gru", func() []string { return cells }, func() time.Time { return now })
	for index, cell := range cells {
		var peers []string
		for _, peer := range cells {
			if peer != cell {
				peers = append(peers, peer)
			}
		}
		observed := now
		if cell == "mel" {
			observed = now.Add(-time.Minute)
		}
		rollup := overviewRollup(cell, observed, peers)
		rollup.Scale = budgetScale(cell, index, observed)
		global.Accept(rollup)
	}
	return global
}

// budgetScale is a region's node scaler: every fourth region grows, every
// fourth from the third is saturated, and the rest hold.
func budgetScale(cell string, index int, observed time.Time) *nodescale.Status {
	scale := &nodescale.Status{Schema: nodescale.StatusSchema, Cell: cell, At: observed, Nodes: 12, QuorumNodes: 3,
		PoolNodes: 9, Want: 12, Allowance: 16, AllowanceFresh: true, Action: nodescale.Hold, Pressure: 0.4,
		Signal: nodescale.SignalCPU, Signals: map[nodescale.Signal]float64{nodescale.SignalCPU: 0.4, nodescale.SignalMemory: 0.3},
		Reason: "every signal <= 0.50 on 11 nodes for 10m0s", LastChange: observed.Add(-time.Hour),
		NodeMonthlyCents: 45000, ProjectedCents: 900000, Currency: "USD"}
	switch index % 4 {
	case 1:
		scale.Action, scale.Want, scale.Pressure, scale.Signal = nodescale.Up, 14, 0.9, nodescale.SignalCPU
		scale.Reason = "cpu 0.90 >= 0.80 for 5m0s"
		scale.InFlight = &nodescale.InFlight{ID: cell + "-launch", Kind: nodescale.Up, Step: "launch", Started: observed}
	case 3:
		scale.Saturated, scale.Pressure = true, 0.95
		scale.Reason = "cpu 0.95 >= 0.80 but the allowance is spent"
	}
	return scale
}

func getGzipped(t *testing.T, handler http.Handler, path string) *httptest.ResponseRecorder {
	t.Helper()
	recorder := httptest.NewRecorder()
	request := httptest.NewRequest(http.MethodGet, path, nil)
	request.Header.Set("Accept-Encoding", "gzip")
	handler.ServeHTTP(recorder, request)
	return recorder
}

func gunzip(t *testing.T, body []byte) []byte {
	t.Helper()
	reader, err := gzip.NewReader(bytes.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	data, err := io.ReadAll(reader)
	if err != nil {
		t.Fatal(err)
	}
	return data
}

type View struct {
	mu          sync.Mutex
	local       string
	regions     func() []string
	now         func() time.Time
	rollups     map[string]*Rollup
	persisted   map[string]time.Time // ObservedAt last written to the bucket
	persistedAt map[string]time.Time // wall time of that write
	changed     chan struct{}
}

// NewView follows every region regions() lists; local is always listed.
// now defaults to time.Now.
func NewView(local string, regions func() []string, now func() time.Time) *View {
	if now == nil {
		now = time.Now
	}
	return &View{
		local:       normalize(local),
		regions:     regions,
		now:         now,
		rollups:     map[string]*Rollup{},
		persisted:   map[string]time.Time{},
		persistedAt: map[string]time.Time{},
		changed:     make(chan struct{}),
	}
}

// Regions lists local first, then every other listed region by cell.
func (v *View) Regions() []Region {
	v.mu.Lock()
	defer v.mu.Unlock()
	cells := v.listed()
	out := make([]Region, 0, len(cells))
	for _, cell := range cells {
		out = append(out, v.region(cell))
	}
	return out
}

// Region returns one listed region; false when cell is not listed.
func (v *View) Region(cell string) (Region, bool) {
	v.mu.Lock()
	defer v.mu.Unlock()
	cell = normalize(cell)
	if !slices.Contains(v.listed(), cell) {
		return Region{}, false
	}
	return v.region(cell), true
}

// Changed returns a channel closed on the next accepted rollup.
func (v *View) Changed() <-chan struct{} {
	v.mu.Lock()
	defer v.mu.Unlock()
	return v.changed
}

// Accept keeps r when it is newer than the held rollup of its cell.
func (v *View) Accept(r Rollup) bool {
	v.mu.Lock()
	defer v.mu.Unlock()
	if validate(r, v.now()) != nil {
		return false
	}
	held := v.rollups[r.Cell]
	if held != nil && !r.ObservedAt.After(held.ObservedAt) {
		return false
	}
	if held == nil && len(v.rollups) >= maxRegions {
		v.prune()
		if len(v.rollups) >= maxRegions {
			return false
		}
	}
	v.rollups[r.Cell] = &r
	close(v.changed)
	v.changed = make(chan struct{})
	return true

package dashboard

import (
	"slices"
	"strconv"
)

// drillRows is how many rows one page of the node or volume list shows.
const drillRows = 50

// nodeSorts are the nodes list's sort keys. name orders by region, then node;
// the others order the largest value first.
var nodeSorts = []string{"name", "cpu", "memory", "disk", "network"}

// pager is one page of a list: rows From up to To of Total, on page Page of Pages.
type pager struct {
	Page, Pages, From, To, Total int
}

// newPager clamps the requested page to the list.
func newPager(total, requested int) pager {
	pages := max(1, (total+drillRows-1)/drillRows)
	page := min(max(requested, 1), pages)
	from := (page - 1) * drillRows
	return pager{Page: page, Pages: pages, From: from, To: min(from+drillRows, total), Total: total}
}

// pageParam reads the 1-based page number; a missing or invalid one is page 1.
func pageParam(current view) int {
	page, _ := strconv.Atoi(current.State.param("page"))
	return page
}

// regionFilterParam is the region a list filters to, or "" for every region.
func regionFilterParam(current view) string {
	if cell := current.State.param("region"); validRegion(cell) {
		return cell
	}
	return ""
}

// sortParam is the nodes list's sort key; an unknown key sorts by name.
func sortParam(current view) string {
	if key := current.State.param("sort"); slices.Contains(nodeSorts, key) {
		return key
	}
	return "name"
}

// nodeList is one page of the nodes list with the filters it was built with.
type nodeList struct {
	Rows   []nodeEntry
	Pager  pager
	Region string
	Sort   string
}

func nodesListOf(current view) nodeList {
	list := nodeList{Region: regionFilterParam(current), Sort: sortParam(current)}
	entries := nodeEntries(current.Global, list.Region, list.Sort)
	list.Pager = newPager(len(entries), pageParam(current))
	list.Rows = entries[list.Pager.From:list.Pager.To]
	return list
}

// volumeList is one page of the volumes list.
type volumeList struct {
	Rows   []volumeEntry
	Pager  pager
	Region string
}

func volumesListOf(current view) volumeList {
	list := volumeList{Region: regionFilterParam(current)}
	entries := volumeEntries(current.Global, list.Region)
	list.Pager = newPager(len(entries), pageParam(current))
	list.Rows = entries[list.Pager.From:list.Pager.To]
	return list
}

func nodeEntries(regions []globalview.Region, region, sortKey string) []nodeEntry {
	var out []nodeEntry
	for _, listed := range regions {
		if listed.Rollup == nil || region != "" && listed.Cell != region {
			continue
		}
		for _, node := range listed.Rollup.Nodes {
			out = append(out, nodeEntry{Region: listed.Cell, Stale: listed.Stale, Node: node})
		}
	}
	slices.SortStableFunc(out, func(left, right nodeEntry) int {
		return cmp.Or(cmp.Compare(nodeMetric(right.Node, sortKey), nodeMetric(left.Node, sortKey)),
			cmp.Compare(left.Region, right.Region), cmp.Compare(left.Node.Name, right.Node.Name))
	})
	return out
}

// nodeMetric is the value a sort key orders a node by.
func nodeMetric(node globalview.Node, sortKey string) float64 {
	switch sortKey {
	case "cpu":
		return valueOr(node.CPU, -1)
	case "memory":
		return ratio(float64(node.MemoryUsedBytes), float64(node.MemoryBytes))
	case "disk":
		return ratio(float64(node.DiskUsedBytes), float64(node.DiskBytes))
	case "network":
		return valueOr(node.NetworkRxBps, 0) + valueOr(node.NetworkTxBps, 0)
	default:
		return 0
	}
}

// valueOr reads an optional reading, or fallback when it was not measured.
func valueOr(value *float64, fallback float64) float64 {
	if value == nil {
		return fallback
	}
	return *value
}

// nodeCells is one node of a node table, already formatted.
type nodeCells struct {
	Region, Name, Status, Health string
	CPU, Memory, Disk, Network   string
	Load, Services, Reported     string
}

func nodeCellsOf(entry nodeEntry, now time.Time) nodeCells {
	node := entry.Node
	cells := nodeCells{Region: entry.Region, Name: node.Name, Status: nodeStatus(node.Health), Health: node.Health,
		CPU: "—", Memory: pctOf(float64(node.MemoryUsedBytes), float64(node.MemoryBytes)),
		Disk:     pctOf(float64(node.DiskUsedBytes), float64(node.DiskBytes)),
		Network:  rateOr(node.NetworkRxBps) + " / " + rateOr(node.NetworkTxBps),
		Load:     "—",
		Services: itoa(len(node.Services)), Reported: age(now, node.ReportedAt)}
	if node.CPU != nil {
		cells.CPU = percent(*node.CPU)
	}
	if node.Load1 != nil {
		cells.Load = formatFloat(*node.Load1, 2)
	}
	if entry.Stale {
		cells.Status, cells.Health = "idle", "stale"
	}
	return cells
}

// regionNodeCells formats one node of region.
func regionNodeCells(region globalview.Region, node globalview.Node, now time.Time) nodeCells {
	return nodeCellsOf(nodeEntry{Region: region.Cell, Stale: region.Stale, Node: node}, now)
}

// regionNodes lists one region's nodes by name.
func regionNodes(region globalview.Region) []nodeEntry {
	return nodeEntries([]globalview.Region{region}, "", "name")
}

func rateOr(value *float64) string {
	if value == nil {
		return "—"
	}
	return rate(*value)
}

// optionalText renders a measurement with its unit, or a dash when it was not measured.
func optionalText(value *float64, unit string) string {
	if value == nil {
		return "—"
	}
	return tenths(*value) + " " + unit
}

// volumeEntry is one volume with the region that reports it.
type volumeEntry struct {
	Region string
	Volume globalview.Volume
}

// volumeEntries lists the volumes of every region, or of region alone, by
// region, node and ID.
func volumeEntries(regions []globalview.Region, region string) []volumeEntry {
	var out []volumeEntry
	for _, listed := range regions {
		if listed.Rollup == nil || region != "" && listed.Cell != region {
			continue
		}
		for _, volume := range listed.Rollup.Volumes {
			out = append(out, volumeEntry{Region: listed.Cell, Volume: volume})
		}
	}
	slices.SortStableFunc(out, func(left, right volumeEntry) int {
		return cmp.Or(cmp.Compare(left.Region, right.Region), cmp.Compare(left.Volume.Node, right.Volume.Node),
			cmp.Compare(left.Volume.ID, right.Volume.ID))
	})
