func NewTokenServer(config Config, token string, deps ServerDeps) (*Server, error) {
	checked, err := checkBearerToken([]byte(token))
	if err != nil {
		return nil, err
	}
	// The token stands in for the file Validate requires off loopback.
	config.BearerTokenFile = "token"
	if err := config.Validate(); err != nil {
		return nil, err
	}
	return newServer(config, checked, deps)
}

func newServer(config Config, token []byte, deps ServerDeps) (*Server, error) {
	if deps.Registry == nil || deps.Health == nil {
		return nil, errors.New("observability server requires a registry and health checks")
	}
	manager := &sessions{secure: config.TLSCertFile != ""}
	if deps.LocalSessions {
		manager.local = make(map[string]struct{})
	}
	server := &Server{mux: http.NewServeMux(), deps: deps, sessions: manager, token: token}
	server.catalog = &metricCatalog{registry: deps.Registry}
	if deps.Sessions != nil && token != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if err := server.SetSessionStore(ctx, deps.Sessions); err != nil {
			return nil, err
		}
	}
	server.mux.HandleFunc("GET /healthz", func(writer http.ResponseWriter, _ *http.Request) {
		writePlain(writer, http.StatusOK, "ok\n")
	})
	server.mux.HandleFunc("GET /readyz", server.readyz)
	server.Handle("GET /metrics", http.HandlerFunc(server.metrics))
	server.HandleAuthenticated("GET /v1/metrics/catalog", http.HandlerFunc(server.metricCatalogHTTP))
	if deps.Snapshots != nil {
		server.HandleSnapshots(deps.Snapshots)
	}
	if deps.Cluster != nil {
		server.HandleCluster(deps.Cluster)
	}
	if deps.Events != nil {
		server.Handle("GET /v1/events", http.HandlerFunc(server.events))
	}
	return server, nil
}

// HandleSnapshots mounts GET /v1/snapshot once a runtime finished wiring
// its providers. A listener started earlier serves health meanwhile. Calling
// it again replaces the source rather than mounting the route twice.
func (server *Server) HandleSnapshots(source SnapshotSource) {
	server.snapshots.Store(&source)
	server.snapshotOnce.Do(func() {

	server.Handle(pattern, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if server.token == nil {
			writePlain(w, http.StatusServiceUnavailable, "authenticated API requires a configured token\n")
			return
		}
		handler.ServeHTTP(w, r)
	}))
}

// HandleStatic mounts an unauthenticated route for public embedded files,
// such as the dashboard's stylesheet the login form needs. It must never
// serve cell state.
func (server *Server) HandleStatic(pattern string, handler http.Handler) {
	server.mux.Handle(pattern, handler)
}

// ServeHTTP lets tests and an embedding mux exercise the routes directly.
func (server *Server) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
	// A proxy hop would make the bind address meaningless as an access
	// control, exactly as for the host enrollment listener.
	if request.Header.Get("Forwarded") != "" || request.Header.Get("X-Forwarded-For") != "" ||
		request.Header.Get("X-Real-IP") != "" {
		writePlain(writer, http.StatusBadRequest, "proxied requests are not accepted\n")
		return
	}
	// Without a token the loopback bind is the only control, and DNS
	// rebinding defeats it for any route reachable under a hostname. Every
	// route of a tokenless listener, not only the dashboard's, therefore
	// requires an IP literal or localhost as the Host.
	if server.token == nil && !LiteralHost(request.Host) {
		writePlain(writer, http.StatusMisdirectedRequest, "address this listener by IP or localhost\n")
		return
	}
	server.mux.ServeHTTP(writer, request)
}

// LiteralHost reports whether an HTTP Host header names an IP literal or
// localhost, which a DNS-rebinding page cannot present.
func LiteralHost(host string) bool {
	if name, _, err := net.SplitHostPort(host); err == nil {
		host = name
	} else if len(host) > 1 && host[0] == '[' && host[len(host)-1] == ']' {
		host = host[1 : len(host)-1]
	}
	if host == "localhost" {
		return true
	}
	_, err := netip.ParseAddr(host)
	return err == nil
}

func (server *Server) authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		if server.token != nil && !bearerMatches(request.Header.Get("Authorization"), server.token) {
			authenticated := false
			if request.Header.Get("Authorization") == "" && server.loginMounted.Load() {
				var err error
				authenticated, err = server.sessions.authenticated(request)
				if err != nil {
					writePlain(writer, http.StatusServiceUnavailable, "session storage unavailable\n")
					return
				}
			}
			if !authenticated {
				if server.loginMounted.Load() && wantsLoginPage(request) {
					http.Redirect(writer, request, "/login?next="+url.QueryEscape(LocalRedirectPath(request.URL.RequestURI())),
						http.StatusSeeOther)
					return
				}
				writer.Header().Set("WWW-Authenticate", `Bearer realm="ts-orch"`)
				writePlain(writer, http.StatusUnauthorized, "unauthorized\n")
				return
			}
		}
		if server.token != nil && server.loginMounted.Load() && request.Header.Get("Authorization") == "" {
			if cookie, err := request.Cookie(SessionCookieName); err == nil {
				http.SetCookie(writer, server.sessions.cookie(cookie.Value))
			}
		}
		next.ServeHTTP(writer, request)
	})
}

package observability

import (
	"net/http"
	"time"
)

// MetricCatalog returns the same live source used by the authenticated API.
// A dashboard can retain it before regional history finishes initializing.
func (server *Server) MetricCatalog() CatalogSource { return server.catalog }

func (server *Server) metricCatalogHTTP(writer http.ResponseWriter, request *http.Request) {
	result, err := server.catalog.Catalog(request.Context())
	if err != nil {
		writePlain(writer, http.StatusServiceUnavailable, "metric catalog unavailable\n")
		return
	}
	writeJSON(writer, result)
}

// HandleMetricHistory installs or replaces the history source shared by the
// catalog, dashboard and API. Callers must not mount HistoryHandler separately.
func (server *Server) HandleMetricHistory(source HistorySource) {
	if source == nil {
		return
	}
	server.catalog.history.Store(&source)
	server.historyOnce.Do(func() {
		server.HandleAuthenticated("GET /v1/history", http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
			query, err := ParseHistoryQuery(request.URL.Query(), time.Now())
			if err != nil {
				writePlain(writer, http.StatusBadRequest, err.Error()+"\n")
				return
			}
			result, err := server.catalog.History(request.Context(), query)
			if err != nil {
				writePlain(writer, http.StatusBadRequest, err.Error()+"\n")
				return
			}
			writeJSON(writer, result)
		}))
		server.HandleAuthenticated("GET /v1/history/metrics", http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
			result, err := server.catalog.Catalog(request.Context())
			if err != nil {
				writePlain(writer, http.StatusServiceUnavailable, "metric catalog unavailable\n")
				return
			}
			names := []string{}
			for _, metric := range result.Metrics {
				if metric.HistoryState == "available" {
					names = append(names, metric.Name)
				}
			}
			writeJSON(writer, names)
		}))
	})
}

func (catalog *metricCatalog) Catalog(ctx context.Context) (CatalogResult, error) {
	if err := ctx.Err(); err != nil {
		return CatalogResult{}, err
	}
	buffer := new(catalogBuffer)
	catalog.registry.WritePrometheus(buffer)
	result := CatalogResult{Version: catalogVersion, ObservedAt: time.Now().UTC(), State: "available", Metrics: []CatalogMetric{}}
	result.Truncated = buffer.truncated
	data := buffer.String()
	if buffer.truncated {
		data, _, _ = strings.CutLast(data, "\n")
	}
	entries := map[string]*CatalogMetric{}
	entry := func(name string) *CatalogMetric {
		if current := entries[name]; current != nil {
			return current
		}
		if len(entries) >= catalogMaxMetrics {
			result.Truncated = true
			return nil
		}
		current := &CatalogMetric{Name: name, Source: "registry", State: "missing", HistoryState: "unsupported", Labels: []string{}, Samples: []CatalogSample{}}
		entries[name] = current
		return current
	}
	// Metadata is optional in Prometheus exposition; never infer type or units
	// from a name suffix when the exporter supplied no metadata.
	for line := range strings.SplitSeq(data, "\n") {
		if len(line) > 65536 {
			result.Truncated = true
			continue
		}
		if !strings.HasPrefix(line, "# ") {
			continue
		}
		kind, rest, ok := strings.Cut(line[2:], " ")
		if !ok || kind != "HELP" && kind != "TYPE" && kind != "UNIT" {
			continue
		}
		name, value, ok := strings.Cut(rest, " ")
		if !ok || !catalogName(name, true) {
			continue
		}
		current := entry(name)
		if current == nil {
			continue
		}
		value = RedactText(strings.TrimSpace(value), 512)
		switch kind {
		case "HELP":
			current.Description = value
		case "UNIT":
			current.Unit = value
		case "TYPE":
			if slices.Contains([]string{"counter", "gauge", "histogram", "summary", "untyped", "info", "stateset"}, value) {
				current.Type = value
			}
		}
	}
	sampleCount := 0
	for line := range strings.SplitSeq(data, "\n") {
		if err := ctx.Err(); err != nil {
			return CatalogResult{}, err
		}
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if len(line) > 65536 {
			result.Truncated = true
			continue
		}
		sample, ok := catalogParseSample(line)
		if !ok {
			result.State = "incomplete"
			continue
		}
		name := sample.Name
		for _, suffix := range []string{"_bucket", "_sum", "_count", "_created"} {
			base, matched := strings.CutSuffix(name, suffix)
			if current := entries[base]; matched && current != nil && (current.Type == "histogram" || current.Type == "summary" || current.Type == "counter") {
				name = base
				break
			}
		}
		current := entry(name)
		if current == nil {
			continue
		}
		current.State, current.ObservedAt = "available", result.ObservedAt
		current.Labels = append(current.Labels, sample.Labels...)
		slices.Sort(current.Labels)
		current.Labels = slices.Compact(current.Labels)
		if len(current.Labels) > catalogMaxLabels {
			current.Labels = current.Labels[:catalogMaxLabels]
			current.State = "truncated"
			result.Truncated = true
		}
		if sampleCount >= catalogMaxSamples || len(current.Samples) >= catalogSamplesPerMetric {
			current.State = "truncated"
			result.Truncated = true
			continue
		}
		current.Samples = append(current.Samples, sample)
		sampleCount++
	}
	if source := catalog.history.Load(); source != nil {
		for _, name := range (*source).Metrics() {
			if !catalogName(name, true) {
				result.State = "incomplete"
				continue
			}
			current := entry(name)
			if current == nil {
				continue
			}
			if current.ObservedAt.IsZero() {
				current.Source, current.State = "history", "missing"
			} else {
				current.Source = "registry,history"
			}
			current.HistoryState = "available"
			current.HistoryTiers = []string{TierRaw, Tier1m, Tier5m, Tier1h}
			current.HistoryRetentionSeconds = int64(HistoryRetention / time.Second)
		}
	}
	for _, name := range slices.Sorted(maps.Keys(entries)) {
		current := entries[name]
		if current.Description == "" {
			current.Unsupported = append(current.Unsupported, "description")
		}
		if current.Unit == "" {
			current.Unsupported = append(current.Unsupported, "unit")
		}
		if current.Type == "" {
			current.Unsupported = append(current.Unsupported, "type")
		}
		if current.ObservedAt.IsZero() {
			current.Unsupported = append(current.Unsupported, "collection_time")
		}
		result.Metrics = append(result.Metrics, *current)
	}
	if result.Truncated {
		result.State = "truncated"
	} else if len(result.Metrics) == 0 {
		result.State = "missing"
	}
	return result, nil

func (catalog *metricCatalog) History(ctx context.Context, query HistoryQuery) (CatalogHistory, error) {
	if err := ctx.Err(); err != nil {
		return CatalogHistory{}, err
	}
	result := CatalogHistory{Version: catalogVersion, ObservedAt: time.Now().UTC(), State: "unsupported", Reason: "history source is not available"}
	if !catalogName(query.Metric, true) {
		return CatalogHistory{}, errors.New("invalid metric name")
	}
	if query.End.IsZero() {
		query.End = result.ObservedAt
	}
	if query.Start.IsZero() {
		query.Start = query.End.Add(-time.Hour)
	}
	if !query.Start.Before(query.End) || query.End.Sub(query.Start) > HistoryRetention {
		return CatalogHistory{}, errors.New("history range must be positive and at most 14 days")
	}
	if !slices.Contains([]string{"", TierRaw, Tier1m, Tier5m, Tier1h}, query.Tier) {
		return CatalogHistory{}, errors.New("invalid history tier")
	}
	if query.MaxSeries <= 0 {
		query.MaxSeries = 64
	}
	query.MaxSeries = min(query.MaxSeries, 512)
	source := catalog.history.Load()
	if source == nil {
		return result, nil
	}
	if !slices.Contains((*source).Metrics(), query.Metric) {
		result.Reason = "metric is not retained by the history source"
		return result, nil
	}
	result.HistoryResult = (*source).Range(query)
	result.State, result.Reason = "missing", "no retained samples in the requested range"
	points := 0
	var newest time.Time
	if len(result.Series) > query.MaxSeries {
		result.Series = result.Series[:query.MaxSeries]
		result.Truncated = true
	}
	for index := range result.Series {
		series := &result.Series[index]
		if len(series.Points) > catalogMaxHistoryPoints-points {
			series.Points = series.Points[:catalogMaxHistoryPoints-points]
			result.Truncated = true
		}
		points += len(series.Points)
		for _, point := range series.Points {
			if point.Time.After(newest) {
				newest = point.Time
			}
		}
	}
	if !newest.IsZero() {
		result.State, result.Reason = "available", ""
		step := DefaultHistoryInterval
		if result.IntervalSeconds > 0 {
			step = time.Duration(result.IntervalSeconds * float64(time.Second))
		}
		for _, series := range result.Series {
			switch series.Tier {
			case Tier1m:
				step = max(step, time.Minute)
			case Tier5m:
				step = max(step, 5*time.Minute)
			case Tier1h:
				step = max(step, time.Hour)
			}
		}
		if query.End.Sub(newest) > 2*step {
			result.State, result.Reason = "stale", "latest retained sample predates the requested range end"
		}
	}
	if result.Incomplete {
		result.State, result.Reason = "incomplete", "retained samples were omitted or rejected"
	}
	if result.Pending {
		result.State, result.Reason = "pending", "regional history replay is pending"
	}
	if result.Truncated {
		result.State, result.Reason = "truncated", "history result exceeded the response budget"
	}
	if result.UnsupportedReason != "" {
		result.State, result.Reason = "unsupported", "rates require a retained counter series"
	}
	return result, ctx.Err()
}

func NewRegistry(processMetrics bool) *Registry {
	metrics.ExposeMetadata(true)
	return &Registry{processMetrics: processMetrics}
}

// Register adds one slice's metric set. Registering the same set twice is a
// no-op.
func (registry *Registry) Register(set *metrics.Set) {
	if registry == nil || set == nil {
		return
	}
	registry.mu.Lock()
	defer registry.mu.Unlock()
	for _, existing := range registry.sets {
		if existing == set {
			return
		}
	}
	registry.sets = append(registry.sets, set)
}

// RegisterWriter adds a scrape-time writer. Writers must be fast or cached:
// a scrape and every cross-member snapshot call them synchronously.
func (registry *Registry) RegisterWriter(write func(io.Writer)) {
	if registry == nil || write == nil {
		return
	}
	registry.mu.Lock()
	defer registry.mu.Unlock()
	registry.writers = append(registry.writers, write)
}

// WritePrometheus renders every registered series in Prometheus text format.
func (registry *Registry) WritePrometheus(w io.Writer) {
	if registry == nil {
		return
	}
	registry.mu.Lock()
	sets := slices.Clone(registry.sets)
	writers := slices.Clone(registry.writers)
	process := registry.processMetrics
	registry.mu.Unlock()
	if process {
		metrics.WriteProcessMetrics(w)
	}
	for _, set := range sets {
		set.WritePrometheus(w)
	}
	for _, write := range writers {
		write(w)
	}
}

func validMetricName(name string) bool {
	if len(name) == 0 || len(name) > 256 {
		return false
	}
	for index, character := range name {
		if character >= 'a' && character <= 'z' || character >= 'A' && character <= 'Z' ||
			character == '_' || character == ':' || index > 0 && character >= '0' && character <= '9' {
			continue
		}
		return false
	}
	return true
}

// loadMetrics keeps registry scrapes and history queries out of template rendering.
func (current *view) loadMetrics(ctx context.Context) {
	if current.Page.slug != "metric-catalog" || current.Journal == nil || current.Journal.Metrics == nil {
		return
	}
	catalog, err := current.Journal.Metrics.Catalog(ctx)
	if err != nil {
		current.Unavailable = append(current.Unavailable, "metric catalog")
		return
	}
	current.MetricCatalog = &catalog
	if metric := current.selectedMetric(); metric != nil {
		history, err := current.Journal.Metrics.History(ctx, observability.HistoryQuery{
			Metric: metric.Name, Start: current.Now.Add(-current.State.Range.Duration), End: current.Now,
			MaxSeries: 32,
		})
		if err != nil {
			current.Unavailable = append(current.Unavailable, "metric history")
			return
		}
		// Keep the newest observations without downsampling across gaps.
		limit := metricHistoryPointLimit / max(len(history.Series), 1)
		for index := range history.Series {
			points := history.Series[index].Points
			if len(points) > limit {
				history.Series[index].Points = points[len(points)-limit:]
				current.MetricHistoryLimited = true
			}
		}
		current.MetricHistory = &history
	}
}

func (current view) selectedMetric() *observability.CatalogMetric {
	if current.MetricCatalog == nil {
		return nil
	}
	for index := range current.MetricCatalog.Metrics {
		if current.MetricCatalog.Metrics[index].Name == current.State.param("metric") {
			return &current.MetricCatalog.Metrics[index]
		}
	}
	return nil
}

func (current view) metricCatalogTable() table {
	listing := table{Caption: "Searchable local metric catalog",
		Headers: []string{"Metric", "Description", "Type / unit", "Source", "State", "History"},
		Empty:   "No metric families match this search."}
	if current.MetricCatalog == nil {
		return listing
	}
	needle := strings.ToLower(current.State.param("q"))
	for _, metric := range current.MetricCatalog.Metrics {
		text := strings.Join([]string{metric.Name, metric.Description, metric.Unit, metric.Type, metric.Source,
			strings.Join(metric.Labels, " "), metric.State, metric.HistoryState}, " ")
		if !strings.Contains(strings.ToLower(text), needle) {
			continue
		}
		listing.Rows = append(listing.Rows, []cell{
			{Text: metric.Name, Href: current.State.keep("/metric-catalog", "metric", metric.Name)},
			textCell(metricMetadata(metric.Description)),
			textCell(metricMetadata(metric.Type) + " / " + metricMetadata(metric.Unit)),
			textCell(metricMetadata(metric.Source)), textCell(metricMetadata(metric.State)),
			textCell(metricMetadata(metric.HistoryState)),
		})
	}
	return listing
}

func metricMetadata(value string) string { return cmp.Or(value, "unsupported") }

func metricDimensions(labels []string) string {
	if len(labels) == 0 {
		return "none reported"
	}
	return strings.Join(labels, ", ")
}

func metricObserved(at time.Time) string {
	if at.IsZero() {
		return "unsupported: collection timestamp unavailable"
	}
	return at.UTC().Format(time.RFC3339Nano)
}

func metricRetention(metric observability.CatalogMetric) string {
	if metric.HistoryRetentionSeconds <= 0 {
		return "unsupported: retention unavailable"
	}
	return (time.Duration(metric.HistoryRetentionSeconds) * time.Second).String()
}

func metricSamplesTable(metric observability.CatalogMetric) table {
	listing := table{Caption: metric.Name + " current samples", Headers: []string{"Sample", "Value", "Label dimensions"},
		Empty: "Missing: no current sample reported. Missing values are not zero."}
	for _, sample := range metric.Samples {
		listing.Rows = append(listing.Rows, []cell{textCell(sample.Name), textCell(sample.Value),
			textCell(metricDimensions(sample.Labels))})
	}
	return listing
}

func metricSeriesName(series observability.HistorySeries) string {
	parts := []string{series.Metric}
	for _, name := range slices.Sorted(maps.Keys(series.Labels)) {
		parts = append(parts, name+"="+series.Labels[name])
	}
	return strings.Join(parts, " ")
}

func (current view) metricInterval() time.Duration {
	if current.MetricHistory != nil && current.MetricHistory.IntervalSeconds > 0 {
		return time.Duration(current.MetricHistory.IntervalSeconds * float64(time.Second))
	}
	return observability.DefaultHistoryInterval
}

func metricStep(tier string, interval time.Duration) time.Duration {
	switch tier {
	case observability.Tier1m:
		return time.Minute
	case observability.Tier5m:
		return 5 * time.Minute
	case observability.Tier1h:
		return time.Hour
	default:
		return interval
	}
}

// metricGap detects missing intervals and partially observed rollup buckets.
func metricGap(series observability.HistorySeries, index int, interval time.Duration) bool {
	point := series.Points[index]
	step := metricStep(series.Tier, interval)
	if index > 0 && point.Time.Sub(series.Points[index-1].Time) > 2*step {
		return true
	}
	return metricPartial(series, index, interval)
}

func metricPartial(series observability.HistorySeries, index int, interval time.Duration) bool {
	point := series.Points[index]
	if series.Tier != observability.TierRaw && point.Samples > 0 {
		return time.Duration(point.Samples)*interval < metricStep(series.Tier, interval)
	}
	return false
}

// metricHistoryChart splits lines at gaps instead of connecting missing observations.
func (current view) metricHistoryChart(metric observability.CatalogMetric) chartSpec {
	spec := current.lineChart("line", metric.Unit, nil, "Missing: no retained samples in this time range.")
	if current.MetricHistory == nil {
		return spec
	}
	for _, series := range current.MetricHistory.Series {
		segment := chartSeries{Name: metricSeriesName(series)}
		flush := func() {
			if len(segment.Points) > 0 {
				spec.Series = append(spec.Series, segment)
				segment.Points = nil
			}
		}
		for index, point := range series.Points {
			if math.IsNaN(point.Value) || math.IsInf(point.Value, 0) {
				flush()
				continue
			}
			if metricGap(series, index, current.metricInterval()) || index > 0 && metricPartial(series, index-1, current.metricInterval()) {
				flush()
			}
			segment.Points = append(segment.Points, [2]float64{float64(point.Time.UnixMilli()), point.Value})
		}
		flush()
	}
	if len(spec.Series) > 0 {
		spec.Empty = ""
	}
	return spec
}

// metricHistoryTable is a bounded text alternative to all charted observations.
func (current view) metricHistoryTable() table {
	listing := table{Caption: "Retained metric observations", Headers: []string{"Series", "Timestamp (UTC)", "Value", "Resolution", "Coverage", "Events"},
		Empty: "No retained samples in this time range."}
	if current.MetricHistory == nil {
		return listing
	}
	for _, series := range current.MetricHistory.Series {
		for index, point := range series.Points {
			coverage := "observed"
			if metricGap(series, index, current.metricInterval()) {
				coverage = "gap / partial observation"
			}
			listing.Rows = append(listing.Rows, []cell{textCell(metricSeriesName(series)),
				textCell(metricObserved(point.Time)), textCell(strconv.FormatFloat(point.Value, 'g', -1, 64)),
				textCell(series.Tier), textCell(coverage),
				{Text: "Events at this time", Href: current.State.link("/events", "at", point.Time.UTC().Format(time.RFC3339))},
			})
		}
	}
	return listing
}

func (current view) metricHistoryWarnings() []string {
	if current.MetricHistory == nil {
		return nil
	}
	history := current.MetricHistory
	var warnings []string
	if history.Reason != "" {
		warnings = append(warnings, history.Reason)
	}
	if history.Truncated {
		warnings = append(warnings, "Truncated: more series exist than this page can show (32 series maximum).")
	}
	if current.MetricHistoryLimited {
		warnings = append(warnings, "Truncated display: only the newest observations are shown within the 1,200-point page budget. Older retained observations remain queryable through the history API.")
	}
	if history.Pending {
		warnings = append(warnings, "Pending: archive replay has not completed; history may be missing.")
	}
	if history.Incomplete {
		warnings = append(warnings, "Incomplete: retained samples were omitted or rejected during replay.")
	}
	gaps := 0
	for _, series := range history.Series {
		for index := range series.Points {
			if metricGap(series, index, current.metricInterval()) {
				gaps++
			}
		}
	}
	if gaps > 0 {
		warnings = append(warnings, fmt.Sprintf("Gaps / partial observations: %d. Chart lines break at these observations; missing values are not zero.", gaps))
	}
	return warnings
}

